contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address target, uint value, bytes memory data) public payable {
        require(address(this).balance >= value);
        address alice = address(0x1234567890123456789012345678901234567890);
        c.withdraw(address(c).balance);
        c.fallback{value: value}();
        uint cBefore = address(c).balance;
        uint aliceBefore = alice.balance;
        bool reverted;
        try c.sendMoney(alice, value, data) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assert(reverted || (alice.balance == aliceBefore + value && address(c).balance + value == cBefore));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address target, uint value, bytes memory data) public payable {
        require(address(this).balance >= value);
        require(target != address(c));
        require(target != address(this));

        uint cBefore = address(c).balance;
        uint targetBefore = target.balance;

        bool reverted;
        try c.sendMoney(target, value, data) {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(!reverted && target.balance == targetBefore + value && address(c).balance + value == cBefore);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint amount) public payable {
        require(address(this).balance >= amount);
        uint beforeCount = c.depositsCount();
        uint beforeBalance = address(c).balance;
        (bool sent, ) = address(c).call{value: amount}("");
        require(sent);
        uint afterCount = c.depositsCount();
        uint afterBalance = address(c).balance;

        assert(afterCount == beforeCount + 1 && afterBalance == beforeBalance + amount);
    }

    receive() external payable {}
}

